import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define fused GEMM + Bias + ReLU CUDA kernel
fused_gemm_bias_relu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cublas_v2.h>

__global__ void fused_bias_relu_kernel(float* output, const float* bias, int rows, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < rows * cols) {
        int col = idx % cols;
        float val = output[idx] + bias[col];
        output[idx] = val > 0 ? val : 0.0f;
    }
}

torch::Tensor fused_gemm_bias_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    cublasHandle_t handle;
    cublasCreate(&handle);

    auto output = torch::zeros({input.size(0), weight.size(0)}, input.options());

    float alpha = 1.0f;
    float beta = 0.0f;
    cublasSgemm(handle, CUBLAS_OP_T, CUBLAS_OP_N,
                output.size(1), output.size(0), input.size(1),
                &alpha,
                weight.data_ptr<float>(), input.size(1),
                input.data_ptr<float>(), input.size(1),
                &beta,
                output.data_ptr<float>(), output.size(1));

    const int block_size = 256;
    int num_elements = output.numel();
    int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_bias_relu_kernel<<<num_blocks, block_size>>>(output.data_ptr<float>(), 
                                                      bias.data_ptr<float>(),
                                                      output.size(0),
                                                      output.size(1));

    cublasDestroy(handle);
    return output;
}
"""

fused_gemm_bias_relu_cpp_source = "torch::Tensor fused_gemm_bias_relu_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

fused_gemm_bias_relu = load_inline(
    name='fused_gemm_bias_relu',
    cpp_sources=fused_gemm_bias_relu_cpp_source,
    cuda_sources=fused_gemm_bias_relu_source,
    functions=['fused_gemm_bias_relu_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, bias_shape):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_op = fused_gemm_bias_relu

    def forward(self, x):
        return self.fused_op.fused_gemm_bias_relu_cuda(x, self.weight, self.bias)
